// ===== BOSS BATTLE SYSTEM =====
// Screen: boss battle - ผู้เล่นเดินหลบท่าโจมตี และยืนบนป้ายคำตอบ

(function() {
  'use strict';

  // ===== CONFIG =====
  const CONFIG = {
    // Movement
    PLAYER_SPEED: 320, // px/s (based on 1280px width)
    ARENA_BOUNDS: { minX: 2, maxX: 94, minY: 2, maxY: 94 }, // % of viewport

