  // ===== HELPER FUNCTIONS =====
  function vwToPx(vw) {
    return (vw / 100) * window.innerWidth;
  }

  function vhToPx(vh) {
    return (vh / 100) * window.innerHeight;
  }

  function pxToVw(px) {
    return (px / window.innerWidth) * 100;
  }

  function pxToVh(px) {
    return (px / window.innerHeight) * 100;
  }

  function distance(x1, y1, x2, y2) {
    return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
  }

  function collide(x1, y1, r1, x2, y2, r2) {
    const dist = distance(x1, y1, x2, y2);
    return dist < (r1 + r2);
  }

  // Random question selector
  function getRandomQuestions(count) {
    const allQuestions = [];
    const planets = ['numberon', 'bionia', 'aksara', 'lingua', 'civilis'];

    planets.forEach(planetId => {
      if (QV.QUESTIONS[planetId]) {
        QV.QUESTIONS[planetId].forEach(zone => {
          zone.forEach(q => {
            allQuestions.push(q);
          });
        });
      }
    });

    // Shuffle and pick
    const shuffled = allQuestions.sort(() => Math.random() - 0.5);
    return shuffled.slice(0, count);
  }

  function shuffleArray(arr) {
    const result = [...arr];
    for (let i = result.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
  }

  // ===== DOM CREATION =====
  function createDOM(bossId) {
    const boss = BOSS_DATA[bossId];

    container = document.createElement('div');
    container.id = 'screen-boss';
    container.className = 'screen-boss';
