  function distance(x1, y1, x2, y2) {
    // x/y เป็น % ของ viewport → แปลงเป็น vw ก่อน (ระยะทางยุคลิดในหน่วย vw)
    const dxPx = (x2 - x1) / 100 * window.innerWidth;
