    const distPx = Math.sqrt(dxPx * dxPx + dyPx * dyPx);
    return (distPx / window.innerWidth) * 100; // หน่วย vw
  }

  function collide(x1, y1, r1, x2, y2, r2) {
    const dist = distance(x1, y1, x2, y2);
    return dist < (r1 + r2);
