      { q: "ทวีปที่ใหญ่ที่สุดในโลกคือทวีปใด", choices: ["แอฟริกา","เอเชีย","อเมริกาเหนือ","ยุโรป"], answerIdx: 1, hint: "ไทยอยู่ทวีปนี้" },
      { q: "เส้นที่แบ่งโลกออกเป็น 2 ซีกเหนือ-ใต้คือ", choices: ["เส้นแวงตะวัน","เส้นศูนย์สูตร","เส้นเมริเดียน","เส้นอาร์กติก"], answerIdx: 1, hint: "Equator ละติจูด 0°" },
      { q: "มหาสมุทรที่ใหญ่ที่สุดคือ", choices: ["แอตแลนติก","อินเดีย","แปซิฟิก","อาร์กติก"], answerIdx: 2, hint: "Pacific Ocean" },
      { q: "แผนที่คืออะไร", choices: ["ภาพถ่ายทางอากาศ","การแทนพื้นที่บนผิวโลกบนกระดาษ","รูปภาพธรรมชาติ","แผนภูมิสถิติ"], answerIdx: 1, hint: "ภาพจำลองพื้นที่" }
    ]
  }
};
