      <div class="skills-overlay" data-action="close-skills"></div>
      <div class="skills-panel">
        <button class="skills-close" data-action="close-skills" aria-label="ปิด">✕</button>
        <h3>📘 คู่มือสกิลการสู้บอส</h3>
        <div class="skills-list">
          <div class="skill-row">
